<?php

namespace MongoDB\Driver;

use MongoDB\BSON\Serializable;
use MongoDB\Driver\Exception\InvalidArgumentException;
use stdClass;

/**
 * <div id="class.mongodb-driver-writeconcern" class="reference"> <h1 class="title">The MongoDB\Driver\WriteConcern class</h1>  <div class="partintro"><p class="verinfo">(mongodb &gt;=1.0.0)</p>  <div class="section" id="mongodb-driver-writeconcern.intro">   <h2 class="title">简介</h2>   <p class="simpara">    <span class="classname"><strong class="classname">MongoDB\Driver\WriteConcern</strong></span> describes the level of    acknowledgement requested from MongoDB for write operations to a standalone    <span class="literal">mongod</span> or to replica sets or to sharded clusters. In    sharded clusters, <span class="literal">mongos</span> instances will pass the write    concern on to the shards.   </p>  </div>  <div class="section" id="mongodb-driver-writeconcern.synopsis">   <h2 class="title">类摘要</h2>   <div class="classsynopsis">    <span class="ooclass"><strong class="classname"></strong></span>    <div class="classsynopsisinfo">     <span class="modifier">final</span>     <span class="ooclass">      <span class="modifier">class</span> <strong class="classname">MongoDB\Driver\WriteConcern</strong>     </span>     <span class="oointerface"><span class="modifier">implements</span>        <a href="https://php.net/manual/zh/class.mongodb-bson-serializable.php" class="interfacename">MongoDB\BSON\Serializable</a></span><span class="oointerface">,  <a href="https://php.net/manual/zh/class.serializable.php" class="interfacename">Serializable</a></span> {</div>    <div class="classsynopsisinfo classsynopsisinfo_comment">// 常量 </div>    <div class="fieldsynopsis">     <span class="modifier">const</span>     <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>      <var class="fieldsynopsis_varname"><a href="https://php.net/manual/zh/class.mongodb-driver-writeconcern.php#mongodb-driver-writeconcern.constants.majority"><var class="varname">MAJORITY</var></a></var><span class="initializer"> = "majority"</span>;</div>    <div class="classsynopsisinfo classsynopsisinfo_comment">// 属性 </div>    <div class="fieldsynopsis"><span class="modifier">public</span>     <span class="modifier">readonly</span>     <span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">null</a></span></span>      <var class="varname"><a href="https://php.net/manual/zh/class.mongodb-driver-writeconcern.php#mongodb-driver-writeconcern.props.w">\$<var class="varname">w</var></a></var>;</div>    <div class="fieldsynopsis"><span class="modifier">public</span>     <span class="modifier">readonly</span>     <span class="type" style="color:#EAB766">?</span><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span><span class="type" style="color:#EAB766"></span></span>      <var class="varname"><a href="https://php.net/manual/zh/class.mongodb-driver-writeconcern.php#mongodb-driver-writeconcern.props.j">\$<var class="varname">j</var></a></var>;</div>    <div class="fieldsynopsis"><span class="modifier">public</span>     <span class="modifier">readonly</span>     <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span>      <var class="varname"><a href="https://php.net/manual/zh/class.mongodb-driver-writeconcern.php#mongodb-driver-writeconcern.props.wtimeout">\$<var class="varname">wtimeout</var></a></var>;</div>    <div class="classsynopsisinfo classsynopsisinfo_comment">// 方法 </div>    <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-driver-writeconcern.bsonserialize.php" class="methodname" style="color:#CC7832">bsonSerialize</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.stdclass.php" class="type stdClass" style="color:#EAB766">stdClass</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-driver-writeconcern.construct.php" class="methodname" style="color:#CC7832">__construct</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></span> <span class="parameter" style="color:#3A95FF">\$w</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></span> <span class="parameter" style="color:#3A95FF">\$wtimeout</span><span class="initializer"> = <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong></span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span></span> <span class="parameter" style="color:#3A95FF">\$journal</span><span class="initializer"> = <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong></span></span>)</div><div class="methodsynopsis dc-description"><span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-driver-writeconcern.getjournal.php" class="methodname" style="color:#CC7832">getJournal</a></span>(): <span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span></span></div><div class="methodsynopsis dc-description"><span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-driver-writeconcern.getw.php" class="methodname" style="color:#CC7832">getW</a></span>(): <span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">null</a></span></span></div><div class="methodsynopsis dc-description"><span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-driver-writeconcern.getwtimeout.php" class="methodname" style="color:#CC7832">getWtimeout</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-driver-writeconcern.isdefault.php" class="methodname" style="color:#CC7832">isDefault</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span></div>   }</div>  </div>  <div class="section" id="mongodb-driver-writeconcern.props">   <h2 class="title">属性</h2>   <dl>         <dt id="mongodb-driver-writeconcern.props.w"><var class="varname">w</var></dt>     <dd>      <span class="simpara">       The write concern value (integer number of nodes, the string       <span class="literal">"majority"</span>, or a custom write concern tag name),       or <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong> if not set.      </span>     </dd>             <dt id="mongodb-driver-writeconcern.props.j"><var class="varname">j</var></dt>     <dd>      <span class="simpara">       Whether write operations must be committed to the journal before       acknowledged, or <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong> if not specified.      </span>     </dd>             <dt id="mongodb-driver-writeconcern.props.wtimeout"><var class="varname">wtimeout</var></dt>     <dd>      <span class="simpara">       The timeout in milliseconds to wait for write concern acknowledgement.       A value of <span class="literal">0</span> means to wait indefinitely.      </span>     </dd>       </dl>  </div>  <div class="section" id="mongodb-driver-writeconcern.constants">   <h2 class="title">预定义常量</h2>   <dl>         <dt id="mongodb-driver-writeconcern.constants.majority"><strong><span>{@link MongoDB\Driver\WriteConcern::MAJORITY}</span></strong></dt>     <dd>      <span class="simpara">       Majority of all the members in the set; arbiters, non-voting members,       passive members, hidden members and delayed members are all included in       the definition of majority write concern.      </span>     </dd>       </dl>  </div>  <div class="section">   <h2 class="title">更新日志</h2>   <table class="doctable informaltable">         <thead>      <tr>       <th>版本</th>       <th>说明</th>      </tr>     </thead>     <tbody class="tbody">      <tr>       <td>PECL mongodb 2.3.0</td>       <td>        Added public <span class="modifier">readonly</span> properties.       </td>      </tr>      <tr>       <td>PECL mongodb 1.7.0</td>       <td>        Implements <span class="interfacename"><a href="https://php.net/manual/zh/class.serializable.php" class="interfacename">Serializable</a></span>.       </td>      </tr>      <tr>       <td>PECL mongodb 1.2.0</td>       <td>        Implements <span class="interfacename"><a href="https://php.net/manual/zh/class.mongodb-bson-serializable.php" class="interfacename">MongoDB\BSON\Serializable</a></span>.       </td>      </tr>     </tbody>       </table>  </div> </div> <h2>目录</h2><ul class="chunklist chunklist_reference"><li>{@link MongoDB\Driver\WriteConcern::bsonSerialize} — Returns an object for BSON serialization</li><li>{@link MongoDB\Driver\WriteConcern::__construct} — Create a new WriteConcern</li><li>{@link MongoDB\Driver\WriteConcern::getJournal} — Returns the WriteConcern's "journal" option</li><li>{@link MongoDB\Driver\WriteConcern::getW} — Returns the WriteConcern's "w" option</li><li>{@link MongoDB\Driver\WriteConcern::getWtimeout} — Returns the WriteConcern's "wtimeout" option</li><li>{@link MongoDB\Driver\WriteConcern::isDefault} — Checks if this is the default write concern</li></ul></div>
 * 
 * WriteConcern controls the acknowledgment of a write operation, specifies the level of write guarantee for Replica Sets.
 */
final class WriteConcern implements Serializable
{
    /**
     * Majority of all the members in the set; arbiters, non-voting members, passive members, hidden members and delayed members are all included in the definition of majority write concern.
     */
    public const MAJORITY = 'majority';

    /**
     * @since 2.3.0
     */
    public readonly string|int|null $w;

    /**
     * @since 2.3.0
     */
    public readonly bool|null $j;

    /**
     * @since 2.3.0
     */
    public readonly int $wtimeout;

    /**
 * <div id="mongodb-driver-writeconcern.construct" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\Driver\WriteConcern::__construct</h1>  <p class="verinfo">(mongodb &gt;=1.0.0)</p><p class="refpurpose"><span class="refname">MongoDB\Driver\WriteConcern::__construct</span> — <span class="dc-title">Create a new WriteConcern</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-driver-writeconcern.construct-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\Driver\WriteConcern::__construct</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></span> <span class="parameter" style="color:#3A95FF">\$w</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></span> <span class="parameter" style="color:#3A95FF">\$wtimeout</span><span class="initializer"> = <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong></span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span></span> <span class="parameter" style="color:#3A95FF">\$journal</span><span class="initializer"> = <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong></span></span>)</div>  <p class="simpara">   Constructs a new <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-writeconcern.php" class="classname">MongoDB\Driver\WriteConcern</a></span>, which is   an immutable value object.  </p> </div> <div class="refsect1 parameters" id="refsect1-mongodb-driver-writeconcern.construct-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">w</span></dt>    <dd>     <p class="para">      </p><table class="doctable table">       <caption><strong>Write concern</strong></caption>               <thead>         <tr>          <th>Value</th>          <th>Description</th>         </tr>        </thead>        <tbody class="tbody">         <tr>          <td>1</td>          <td>            Requests acknowledgement that the write operation has propagated to            the standalone <span class="literal">mongod</span> or the primary in a replica            set. This is the default write concern for MongoDB.          </td>         </tr>         <tr>          <td>0</td>          <td>           Requests no acknowledgment of the write operation. However, this may           return information about socket exceptions and networking errors to           the application.          </td>         </tr>         <tr>          <td>&lt;integer greater than 1&gt;</td>          <td>           Numbers greater than 1 are valid only for replica sets to request           acknowledgement from specified number of members, including the           primary.          </td>         </tr>         <tr>          <td><strong><span>{@link MongoDB\Driver\WriteConcern::MAJORITY}</span></strong></td>          <td>           <span class="simpara">            Requests acknowledgment that write operations have propagated to the            majority of voting nodes, including the primary, and have been            written to the on-disk journal for these nodes.           </span>           <span class="simpara">            Prior to MongoDB 3.0, this refers to the majority of replica set            members (not just voting nodes).           </span>          </td>         </tr>         <tr>          <td>string</td>          <td>           A string value is interpereted as a tag set. Requests acknowledgement           that the write operations have propagated to a replica set member           with the specified tag.          </td>         </tr>        </tbody>             </table>         </dd>          <dt><span class="parameter" style="color:#3A95FF">wtimeout</span></dt>    <dd>     <span class="simpara">      How long to wait (in milliseconds) for secondaries before failing.     </span>     <span class="simpara">      <span class="literal">wtimeout</span> causes write operations to return with an      error (<span class="classname"><strong class="classname">WriteConcernError</strong></span>) after the specified      limit, even if the required write concern will eventually succeed. When      these write operations return, MongoDB does not undo successful data      modifications performed before the write concern exceeded the      <span class="literal">wtimeout</span> time limit.     </span>     <span class="simpara">      If specified, <span class="literal">wtimeout</span> must be a signed 64-bit integer      greater than or equal to zero.     </span>     <p class="para">      </p><table class="doctable table">       <caption><strong>Write concern timeout</strong></caption>               <thead>         <tr>          <th>Value</th>          <th>Description</th>         </tr>        </thead>        <tbody class="tbody">         <tr>          <td>0</td>          <td>Block indefinitely. This is the default.</td>         </tr>         <tr>          <td>&lt;integer greater than 0&gt;</td>          <td>           Milliseconds to wait until returning.          </td>         </tr>        </tbody>             </table>         </dd>          <dt><span class="parameter" style="color:#3A95FF">journal</span></dt>    <dd>     <span class="simpara">      Wait until mongod has applied the write to the journal.     </span>    </dd>     </dl> </div> <div class="refsect1 errors" id="refsect1-mongodb-driver-writeconcern.construct-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li>   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> if <span class="parameter" style="color:#3A95FF">w</span> is invalid or <span class="parameter" style="color:#3A95FF">wtimeout</span> is either negative or greater than the bounds of a signed 32-bit integer.</li>  </ul> </div> <div class="refsect1 changelog" id="refsect1-mongodb-driver-writeconcern.construct-changelog">  <h3 class="title">更新日志</h3>  <table class="doctable informaltable">       <thead>     <tr>      <th>版本</th>      <th>说明</th>     </tr>    </thead>    <tbody class="tbody">     <tr>      <td>PECL mongodb 1.7.0</td>      <td>       The <span class="parameter" style="color:#3A95FF">wTimeout</span> parameter now accepts 64-bit values.      </td>     </tr>    </tbody>     </table> </div> <div class="refsect1 examples" id="refsect1-mongodb-driver-writeconcern.construct-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">MongoDB\Driver\WriteConcern::__construct()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br><br></span><span style="color: #FF8000">// Request write acknowledgement from the majority of the replica set nodes <br></span><span style="color: #9876AA">\$wc </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\WriteConcern</span><span style="color: #007700">(</span><span style="color: #9876AA">MongoDB\Driver\WriteConcern</span><span style="color: #007700">::</span><span style="color: #9876AA">MAJORITY</span><span style="color: #007700">, </span><span style="color: #9876AA">500</span><span style="color: #007700">);<br><br></span><span style="color: #FF8000">// Request write acknowledgement from a node configured with the "MultipleDC" tag <br></span><span style="color: #9876AA">\$wc </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\WriteConcern</span><span style="color: #007700">(</span><span style="color: #DD0000">"MultipleDC"</span><span style="color: #007700">, </span><span style="color: #9876AA">500</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>  </div> </div> <div class="refsect1 seealso" id="refsect1-mongodb-driver-writeconcern.construct-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><a href="https://www.mongodb.com/docs/manual/reference/write-concern/" class="link external">»&nbsp;Write Concern reference</a></li>  </ul> </div></div>
 * 
     * Construct immutable WriteConcern
     * @link https://php.net/manual/zh/mongodb-driver-writeconcern.construct.php
     * @param string|int $w
     * @param int|null $wtimeout How long to wait (in milliseconds) for secondaries before failing.
     * @param bool|null $journal Wait until mongod has applied the write to the journal.
     * @throws InvalidArgumentException on argument parsing errors.
     */
    final public function __construct(string|int $w, ?int $wtimeout = null, ?bool $journal = null) {}


    public static function __set_state(array $properties) {}

    /**
 * <div id="mongodb-driver-writeconcern.getjournal" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\Driver\WriteConcern::getJournal</h1>  <p class="verinfo">(mongodb &gt;=1.0.0)</p><p class="refpurpose"><span class="refname">MongoDB\Driver\WriteConcern::getJournal</span> — <span class="dc-title">Returns the WriteConcern's "journal" option</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-driver-writeconcern.getjournal-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\Driver\WriteConcern::getJournal</strong></span>(): <span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span></span></div> </div> <div class="refsect1 parameters" id="refsect1-mongodb-driver-writeconcern.getjournal-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-driver-writeconcern.getjournal-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns the WriteConcern's "journal" option.  </p> </div> <div class="refsect1 errors" id="refsect1-mongodb-driver-writeconcern.getjournal-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li>  </ul> </div> <div class="refsect1 examples" id="refsect1-mongodb-driver-writeconcern.getjournal-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">MongoDB\Driver\WriteConcern::getJournal()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br><br>\$wc </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\WriteConcern</span><span style="color: #007700">(</span><span style="color: #9876AA">1</span><span style="color: #007700">);<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$wc</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getJournal</span><span style="color: #007700">());<br><br></span><span style="color: #9876AA">\$wc </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\WriteConcern</span><span style="color: #007700">(</span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #9876AA">0</span><span style="color: #007700">, </span><span style="color: #9876AA">true</span><span style="color: #007700">);<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$wc</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getJournal</span><span style="color: #007700">());<br><br></span><span style="color: #9876AA">\$wc </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\WriteConcern</span><span style="color: #007700">(</span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #9876AA">0</span><span style="color: #007700">, </span><span style="color: #987