    /**
 * <div id="mongodb-driver-writeconcern.bsonserialize" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\Driver\WriteConcern::bsonSerialize</h1>  <p class="verinfo">(mongodb &gt;=1.2.0)</p><p class="refpurpose"><span class="refname">MongoDB\Driver\WriteConcern::bsonSerialize</span> — <span class="dc-title">Returns an object for BSON serialization</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-driver-writeconcern.bsonserialize-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\Driver\WriteConcern::bsonSerialize</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.stdclass.php" class="type stdClass" style="color:#EAB766">stdClass</a></span></div> </div> <div class="refsect1 parameters" id="refsect1-mongodb-driver-writeconcern.bsonserialize-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-driver-writeconcern.bsonserialize-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns an object for serializing the WriteConcern as BSON.  </p> </div> <div class="refsect1 errors" id="refsect1-mongodb-driver-writeconcern.bsonserialize-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li>  </ul> </div> <div class="refsect1 examples" id="refsect1-mongodb-driver-writeconcern.bsonserialize-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">MongoDB\Driver\WriteConcern::bsonSerialize()</strong></span> with majority write concern</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br><br>\$wc </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\WriteConcern</span><span style="color: #007700">(</span><span style="color: #9876AA">MongoDB\Driver\WriteConcern</span><span style="color: #007700">::</span><span style="color: #9876AA">MAJORITY</span><span style="color: #007700">);<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$wc</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">bsonSerialize</span><span style="color: #007700">());<br><br>echo </span><span style="color: #DD0000">"\n"</span><span style="color: #007700">, </span><span style="color: #9876AA">MongoDB\BSON\Document</span><span style="color: #007700">::</span><span style="color: #9876AA">fromPHP</span><span style="color: #007700">(</span><span style="color: #9876AA">\$wc</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">toRelaxedExtendedJSON</span><span style="color: #007700">();<br><br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">object(stdClass)#2&nbsp;(1)&nbsp;{<br>&nbsp;&nbsp;["w"]=&gt;<br>&nbsp;&nbsp;string(8)&nbsp;"majority"<br>}<br><br>{&nbsp;"w"&nbsp;:&nbsp;"majority"&nbsp;}</blockquote></div>   </div>  </div><div class="example" id="example-2">   <p><strong>示例 #2 <span class="function"><strong style="color:#CC7832">MongoDB\Driver\WriteConcern::bsonSerialize()</strong></span> with wtimeout and journal</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br><br>\$wc </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\WriteConcern</span><span style="color: #007700">(</span><span style="color: #9876AA">2</span><span style="color: #007700">, </span><span style="color: #9876AA">1000</span><span style="color: #007700">, </span><span style="color: #9876AA">true</span><span style="color: #007700">);<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$wc</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">bsonSerialize</span><span style="color: #007700">());<br><br>echo </span><span style="color: #DD0000">"\n"</span><span style="color: #007700">, </span><span style="color: #9876AA">MongoDB\BSON\Document</span><span style="color: #007700">::</span><span style="color: #9876AA">fromPHP</span><span style="color: #007700">(</span><span style="color: #9876AA">\$wc</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">toRelaxedExtendedJSON</span><span style="color: #007700">();<br><br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">object(stdClass)#2&nbsp;(3)&nbsp;{<br>&nbsp;&nbsp;["w"]=&gt;<br>&nbsp;&nbsp;int(2)<br>&nbsp;&nbsp;["j"]=&gt;<br>&nbsp;&nbsp;bool(true)<br>&nbsp;&nbsp;["wtimeout"]=&gt;<br>&nbsp;&nbsp;int(1000)<br>}<br><br>{&nbsp;"w"&nbsp;:&nbsp;2,&nbsp;"j"&nbsp;:&nbsp;true,&nbsp;"wtimeout"&nbsp;:&nbsp;1000&nbsp;}</blockquote></div>   </div>  </div> </div> <div class="refsect1 seealso" id="refsect1-mongodb-driver-writeconcern.bsonserialize-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="methodname" style="color:#CC7832">{@link MongoDB\BSON\Serializable::bsonSerialize()} - Provides an array or document to serialize as BSON</span></li>   <li><a href="https://www.mongodb.com/docs/manual/reference/write-concern/" class="link external">»&nbsp;Write Concern reference</a></li>  </ul> </div></div>
 * 
