/**
 * <div id="mongodb-driver-writeconcern.isdefault" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\Driver\WriteConcern::isDefault</h1>  <p class="verinfo">(mongodb &gt;=1.3.0)</p><p class="refpurpose"><span class="refname">MongoDB\Driver\WriteConcern::isDefault</span> — <span class="dc-title">Checks if this is the default write concern</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-driver-writeconcern.isdefault-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\Driver\WriteConcern::isDefault</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span></div>  <p class="simpara">   Returns whether this is the default write concern (i.e. no options are   specified). This method is primarily intended to be used in conjunction with   <span class="methodname" style="color:#CC7832">{@link MongoDB\Driver\Manager::getWriteConcern()}</span> to determine   whether the Manager has been constructed without any write concern options.  </p>  <p class="simpara">   The driver will not include a default write concern in its write operations   (e.g. <span class="methodname" style="color:#CC7832">{@link MongoDB\Driver\Manager::executeBulkWrite()}</span>) in   order to allow the server to apply its own default, which may have been   <a href="https://www.mongodb.com/docs/manual/core/replica-set-write-concern/#modify-default-write-concern" class="link external">»&nbsp;modified</a>.   Libraries that access the Manager's write concern to include it in their own   write commands should use this method to ensure that default write concerns   are left unset.  </p> </div> <div class="refsect1 parameters" id="refsect1-mongodb-driver-writeconcern.isdefault-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-driver-writeconcern.isdefault-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.true">true</a></span></strong> if this is the default write concern and <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.false">false</a></span></strong> otherwise.  </p> </div> <div class="refsect1 errors" id="refsect1-mongodb-driver-writeconcern.isdefault-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li>  </ul> </div> <div class="refsect1 examples" id="refsect1-mongodb-driver-writeconcern.isdefault-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">MongoDB\Driver\WriteConcern::isDefault()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br><br>\$wc </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\WriteConcern</span><span style="color: #007700">(</span><span style="color: #9876AA">1</span><span style="color: #007700">);<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$wc</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">isDefault</span><span style="color: #007700">());<br><br></span><span style="color: #9876AA">\$manager </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\Manager</span><span style="color: #007700">(</span><span style="color: #DD0000">'mongodb://127.0.0.1/?w=majority'</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$wc </span><span style="color: #007700">= </span><span style="color: #9876AA">\$manager</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getWriteConcern</span><span style="color: #007700">();<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$wc</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">isDefault</span><span style="color: #007700">());<br><br></span><span style="color: #9876AA">\$manager </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\Manager</span><span style="color: #007700">(</span><span style="color: #DD0000">'mongodb://127.0.0.1/'</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$wc </span><span style="color: #007700">= </span><span style="color: #9876AA">\$manager</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getWriteConcern</span><span style="color: #007700">();<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$wc</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">isDefault</span><span style="color: #007700">());<br><br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例会输出：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">bool(false)<br>bool(false)<br>bool(true)</blockquote></div>   </div>  </div> </div> <div class="refsect1 seealso" id="refsect1-mongodb-driver-writeconcern.isdefault-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="methodname" style="color:#CC7832">{@link MongoDB\Driver\Manager::getWriteConcern()} - Return the WriteConcern for the Manager</span></li>   <li><a href="https://www.mongodb.com/docs/manual/core/replica-set-write-concern/#modify-default-write-concern" class="link external">»&nbsp;Modify Default Write Concern</a> in the MongoDB manual</li>   <li><a href="https://www.mongodb.com/docs/manual/reference/write-concern/" class="link external">»&nbsp;Write Concern reference</a></li>  </ul> </div></div>
 */
    final public function isDefault(): bool {}
}
